WITH with_windows AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, ROUND(salary / SUM(salary) OVER (PARTITION BY level, dept_id), 4) salary_share, FIRST_VALUE(level, TRUE) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_level FROM employees) SELECT s.id, s.full_name, s.email, s.manager_id, s.salary, s.hire_date, s.is_remote, s.level, s.salary_share, (SELECT SUM(e2.salary) FROM employees e2 WHERE e2.manager_id = s.manager_id) AS sum_employee_salary FROM with_windows s ORDER BY manager_id DESC NULLS FIRST
